/* js/ta/faq.js — Ask Tommy's FAQ bank as ONE Tommy Script command: faq id="reg3".
 *
 * Data: window.TA_FAQ (js/ta/faq-data.js, generated by scripts/build_faq.py from USC pages in data/kb.json.gz). Each
 * entry has 3-8 question paraphrases, a short answer that is the source page's own text, and its source URLs.
 * Matching is deterministic: a keyword index (token -> entries) scores the student's words against each paraphrase
 * (idf-weighted overlap, both directions). Three ways in:
 *   1. the AI translator picks `faq {id}` from the catalogue line (ids + short titles);
 *   2. on device, a message that is (nearly) one of an entry's paraphrases compiles to faq straight away;
 *   3. when Trojan Assist's own brain has no answer at all, a looser match is tried before giving up.
 * Crisis, safety and personal messages never reach this file's matching: TS.handle sends them to Trojan Assist first,
 * and the fallback in (3) checks the same flags again. Load after scripts-plus.js. */
(function () {
  'use strict';
  var TA = window.TA, TS = TA && TA.Script, DATA = window.TA_FAQ;
  if (!TS || !TS.cmds || !Array.isArray(DATA) || !DATA.length) return;

  var STOP = {};
  ('a an the and or but if then so to of in on at for from by with about as into than too very can could would should will shall may might must do does did ' +
   'doing done i im me my mine we our you your u ur it its is are was were be been being am have has had having what whats which who whom whose when where why ' +
   'how this that these those there here any some all each every no not just also only still yet get got getting please tell know want need usc trojan ' +
   'thanks hi hey ok okay really actually like much many more most one way go going there s t')
    .split(' ').forEach(function (w) { STOP[w] = 1; });
  var SYN = { regist: 'register', registration: 'register', registering: 'register', enroll: 'register', enrolling: 'register', signup: 'register',
    classes: 'class', course: 'class', courses: 'class', prof: 'professor', profs: 'professor', instructor: 'professor', dorm: 'housing', dorms: 'housing',
    uscard: 'idcard', id: 'idcard', fafsa: 'fafsa', finaid: 'aid', wifi: 'wifi', laptop: 'computer', laptops: 'computer', pc: 'computer',
    cost: 'price', costs: 'price', fee: 'price', fees: 'price', pay: 'payment', paying: 'payment', paid: 'payment', payments: 'payment',
    refund: 'refund', refunds: 'refund', drop: 'drop', dropping: 'drop', withdraw: 'withdraw', withdrawal: 'withdraw', transcript: 'transcript', transcripts: 'transcript',
    grad: 'graduate', graduation: 'graduate', graduating: 'graduate', gpa: 'gpa', international: 'international', intl: 'international',
    apt: 'apartment', apartments: 'apartment', roommate: 'roommate', roommates: 'roommate', email: 'email', emails: 'email', password: 'password', pw: 'password' };
  function stem(w) {
    if (SYN[w]) return SYN[w];
    if (w.length > 5 && /ies$/.test(w)) return w.slice(0, -3) + 'y';
    if (w.length > 4 && /[^s]s$/.test(w)) return w.slice(0, -1);
    if (w.length > 6 && /ing$/.test(w)) return w.slice(0, -3);
    if (w.length > 5 && /ed$/.test(w)) return w.slice(0, -2);
    return w;
  }
  function toks(s) {
    var out = [], seen = {};
    String(s || '').toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).forEach(function (w) {
      if (!w || STOP[w] || (w.length < 2 && !/\d/.test(w))) return;
      w = stem(w); if (!seen[w]) { seen[w] = 1; out.push(w); }
    });
    return out;
  }

  // ------------------------------------------------------------------ index (built once, lazily)
  var IX = null;
  function build() {
    if (IX) return IX;
    var inv = {}, df = {}, byId = {}, N = DATA.length;
    DATA.forEach(function (e, i) {
      byId[e.id] = e;
      e._p = (e.q || []).map(toks).filter(function (p) { return p.length; });
      var all = {}; e._p.forEach(function (p) { p.forEach(function (w) { all[w] = 1; }); });
      toks(e.t).forEach(function (w) { all[w] = 1; });
      (e.k || []).forEach(function (k) { toks(k).forEach(function (w) { all[w] = 1; }); });
      Object.keys(all).forEach(function (w) { (inv[w] = inv[w] || []).push(i); df[w] = (df[w] || 0) + 1; });
    });
    var idf = {}; Object.keys(df).forEach(function (w) { idf[w] = Math.log(1 + N / df[w]); });
    IX = { inv: inv, idf: idf, byId: byId, N: N };
    return IX;
  }
  function w8(w) { var x = IX.idf[w]; return x == null ? Math.log(1 + IX.N) : x; }
  // text -> [{e, s, cov}] best first. s = F1 of idf-weighted overlap with the best paraphrase (title as a fallback paraphrase)
  function search(text, n) {
    build();
    var t = toks(text); if (!t.length) return [];
    var tw = t.reduce(function (a, w) { return a + w8(w); }, 0), cand = {};
    t.forEach(function (w) { (IX.inv[w] || []).forEach(function (i) { cand[i] = (cand[i] || 0) + w8(w); }); });
    var ids = Object.keys(cand).sort(function (a, b) { return cand[b] - cand[a]; }).slice(0, 60), res = [];
    ids.forEach(function (i) {
      var e = DATA[i], best = 0, bcov = 0;
      e._p.concat([toks(e.t)]).forEach(function (p) {
        var hit = 0, pw = 0; p.forEach(function (w) { var x = w8(w); pw += x; if (t.indexOf(w) >= 0) hit += x; });
        if (!hit) return;
        var ct = hit / tw, cp = hit / pw, f = 2 * ct * cp / (ct + cp);
        if (f > best) { best = f; bcov = ct; }
      });
      if (best > 0) res.push({ e: e, s: best, cov: bcov });
    });
    res.sort(function (a, b) { return b.s - a.s; });
    return res.slice(0, n || 5);
  }
  function confident(text, strict) {
    var r = search(text, 3); if (!r.length) return null;
    var a = r[0], b = r[1], t = toks(text);
    if (t.length < 2) return null;
    if (strict) return a.s >= 0.86 && a.cov >= 0.85 && (!b || a.s - b.s >= 0.12) ? a : null;
    return a.s >= 0.6 && a.cov >= 0.6 && (!b || a.s - b.s >= 0.06) ? a : null;
  }

  function answer(e, how) {
    return [{ role: 'bot', kind: 'c', md: '**' + e.t + '**\n\n' + e.a, chips: [], sources: (e.s || []).slice(0, 2), faq: { id: e.id, how: how } }];
  }

  // ------------------------------------------------------------------ the command
  // personal / sensitive wording and Trojan Assist's safety flags: never answered from the FAQ bank on device
  function blocked(text) {
    try {
      var n = TA.NLU.parse(text), P = TS.PERSONAL || PERS;
      return !!(n.crisis || n.emergency || n.distress || n.disclose || n.threat || n.threatMe || n.violence || n.hazing || n.concern || n.medical || n.overdose ||
        (TA.Hub && TA.Hub.flagged && TA.Hub.flagged(n)) || (TA.Hub && TA.Hub.dangerText && TA.Hub.dangerText(n)) || (TA.Brain && TA.Brain.sensitive && TA.Brain.sensitive(n)) ||
        (P && P.test(String(text).toLowerCase())) || /\b(haz(e|ed|es|ing)|harass\w*|bull(y|ied|ying)|stalk\w*|unsafe|scared|afraid|threat\w*|help me now)\b/.test(String(text).toLowerCase()));
    } catch (e) { return true; }
  }
  // the same personal-topics list script.js uses before it ever calls the AI (it sets TS.PERSONAL on the first message)
  var PERS = /\b(pregnan\w*|abortion|contracepti\w*|plan b|birth control|stds?|stis?|hiv|sexual\w*|rape|assault\w*|abus\w*|harass\w*|diagnos\w*|depress\w*|anxi\w*|panic attacks?|adhd|autis\w*|bipolar|ptsd|therap\w*|counsel\w*|psychiatr\w*|medicat\w*|prescription\w*|eating disorder|anorexi\w*|bulimi\w*|self.?harm|suicid\w*|overdos\w*|addict\w*|drunk|high on|drugs?|disabilit\w*|immigra\w*|undocumented|daca|visa status|deport\w*|lgbt\w*|gay|lesbian|transgender|coming out|ssn|social security number)\b/;
  var DO = /^(please |can you |could you |hey tommy |tommy )*(register|enroll|sign me up|drop|add|book|reserve|order|cancel|pay|request|schedule|renew|change|switch|apply|submit|send|file|get me|set up|update)\b/;

  TS.cmds.faq = {
    name: 'faq', args: ['id'], plus: true, public: true, // answers are USC page text only
    about: 'Answer from a USC FAQ page for topics NOT covered by the commands above. id: one id from this list (pick the title that matches the question): ' +
      DATA.map(function (e) { return e.id + ' ' + e.t; }).join('; '),
    match: function (t, raw) {
      if (!TA.FAQ.strict || DO.test(t) || blocked(raw)) return null;
      var m = confident(raw, true); return m ? { id: m.e.id } : null;
    },
    run: function (a) {
      build();
      var id = String((a && a.id) || '').trim(), e = IX.byId[id] || IX.byId[id.toLowerCase()];
      if (!e && id) { var m = search(id, 1)[0]; if (m && m.s >= 0.5) e = m.e; }
      if (!e) return [{ role: 'bot', kind: 'none', md: 'I don’t have a USC FAQ answer for that. Try asking it another way.', chips: [] }];
      return answer(e, 'id');
    }
  };

  // when Trojan Assist's own brain finds nothing at all, try a looser FAQ match before saying so
  var B = TA.Brain;
  function missed(out) { return !out || !out.length || (out.some(function (m) { return m && (m.kind === 'none' || m.kind === 'off'); }) && !out.some(function (m) { return m && m.card; })); }
  if (B && typeof B.handle === 'function') {
    var h0 = B.handle;
    B.handle = async function (text) {
      var out = await h0.apply(this, arguments);
      try {
        if (missed(out) && !B.pending && typeof text === 'string' && text.charAt(0) !== '@' && !blocked(text)) {
          var t = TA.NLU.normalize ? TA.NLU.normalize(text) : text.toLowerCase();
          if (!DO.test(t)) { var m = confident(text, false); if (m) return answer(m.e, 'fallback'); }
        }
      } catch (e) { /* keep the brain's own answer */ }
      return out;
    };
  }

  // build the index when the page is idle, so no message pays for it
  setTimeout(function () { try { build(); } catch (e) { /* built on first use instead */ } }, 0);

  if (!TS.isPublic) TS.isPublic = function (name) { return !!(TS.cmds[name] && TS.cmds[name].public === true); };

  TA.FAQ = { strict: false, search: search, confident: confident, toks: toks, data: DATA, count: DATA.length,
    catalogChars: function () { return TS.cmds.faq.about.length; } };
})();
